void tmr_irq_service( void )
{
	UInt8 i ; 

    Tmr_Irq tmr_irq ;

    tmr_irq_tc = TMR_IRQ_TC ;

    for( i = 0 ; i < TMR_IRQ_COUNT ; i++ )
    {
        tmr_irq = tmr_irq_table[i];
        
        if( tmr_irq != NULL )
        {                        
            if( tmr_irq->service_vector )
            {
                (tmr_irq->service_vector)();
            }
        }
    }
}

